/bin/bash -c "python3 - <<'PY'
from fractions import Fraction as F

def eta(a,b):
 if a==b: return F(0)
 return 1-b/a if b<a else 1-(1-b)/(1-a)

def binary_dcp(ps):
 candidates=set(ps)|{F(0),F(1)}
 return min(sum((eta(a,p) for p in ps),F(0))/len(ps) for a in candidates)
original=[F(1,2),F(1,2)]
perturbed=[F(2,5),F(3,5)]
tv=sum(abs(x-y) for x,y in zip(original,perturbed))/2
print('Stability check, equal groups and identical conditional rows for each true label:')
print('Original DCP:',binary_dcp(original),'Perturbed DCP:',binary_dcp(perturbed),'Joint total variation:',tv)

def surrogate(a,b):
 if a==b: return F(0)
 return a*a-a*b if b<a else (1-a)**2-(1-b)*(1-a)
left=(F(11,20),F(1,5))
right=(F(13,20),F(2,5))
mid=tuple((x+y)/2 for x,y in zip(left,right))
print('Convexity check for Eq. 18:')
print('Midpoint:',mid,'value:',surrogate(*mid),'average endpoint value:',(surrogate(*left)+surrogate(*right))/2)
print('Hessian on b<a is [[2,-1],[-1,0]], determinant = -1.')
eps=F(1,100000)
print('Smoothing check: original DCP',binary_dcp([F(0),F(1)]),'smoothed optimum',float(binary_dcp([eps,1-eps])))
PY"
